// Generated by scripts/build.js. Edit scripts/sw.template.js instead.
// Online: always ask the network for the newest file. If the network is slow (6 s) or off, use the saved copy.
// IMPORTANT: install and activate must stay tiny. A worker that is still 'activating' holds back every page
// request, so downloading hundreds of files there leaves the app on a blank screen after an update.
// Pages and lessons are saved as they are used. A handful of core files are warmed up later, on request.
const V='polis-__VERSION__',FILES=__FILES__;
const WARM=FILES.filter(f=>f==='./'||f==='fonts/fonts.css'||(!f.includes('/')&&/\.(html|js|css|json|webmanifest)$/.test(f)));
self.addEventListener('install',e=>{e.waitUntil(self.skipWaiting())});
self.addEventListener('activate',e=>{e.waitUntil((async()=>{
  for(const k of await caches.keys())if(k!==V&&k!==V+'-fonts')await caches.delete(k);
  await self.clients.claim()})())});
self.addEventListener('message',e=>{if(e.data==='warm')e.waitUntil((async()=>{const c=await caches.open(V);
  for(const f of WARM){try{if(!(await c.match(f)))await c.add(new Request(f,{cache:'no-cache'}))}catch(err){}}})())});
self.addEventListener('fetch',e=>{
  const u=new URL(e.request.url);if(e.request.method!=='GET')return;
  if(u.host.endsWith('googleapis.com')||u.host.endsWith('gstatic.com')){
    e.respondWith(caches.open(V+'-fonts').then(c=>c.match(e.request).then(r=>r||fetch(e.request).then(n=>{c.put(e.request,n.clone());return n}))));return}
  if(u.origin!==location.origin||u.pathname.startsWith('/api/'))return;
  e.respondWith((async()=>{
    const c=await caches.open(V),saved=await c.match(e.request,{ignoreSearch:true});
    const net=fetch(e.request,{cache:'no-cache'}).then(n=>{if(n.ok){const cp=n.clone();c.put(e.request,cp).catch(()=>{})}return n});
    if(!saved)return net;                                   // nothing saved yet: the network is the only source
    return Promise.race([net.catch(()=>saved),new Promise(r=>setTimeout(()=>r(saved),6000))])})())});
self.addEventListener('push',e=>{let d={};try{d=e.data.json()}catch(x){d={title:'Light Bulb',body:e.data&&e.data.text()}}
  e.waitUntil(self.registration.showNotification(d.title||'Light Bulb',{body:d.body||'',icon:'icons/icon-192.png',badge:'icons/icon-192.png',tag:'daily',renotify:true,data:{url:d.url||'./'}}))});
self.addEventListener('notificationclick',e=>{e.notification.close();const url=new URL(e.notification.data.url,self.location.origin).href;
  e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(cs=>{for(const c of cs){if('focus' in c){c.navigate(url);return c.focus()}}return clients.openWindow(url)}))});
